select id, tenant_id, equipment_code, equipment_name, area_id, unit_id, equipment_type, running_status, status, created_at, updated_at, deleted from base_equipment where tenant_id = #{tenantId} and deleted = 0
and (equipment_code like concat('%', #{keyword}, '%') or equipment_name like concat('%', #{keyword}, '%'))
and status = #{status}
order by id desc limit #{limit} offset #{offset}

select count(1) from base_equipment where tenant_id = #{tenantId} and deleted = 0
and (equipment_code like concat('%', #{keyword}, '%') or equipment_name like concat('%', #{keyword}, '%'))
and status = #{status}
